-- 002: Pre-Built Report (2 Photos per Page)
--
-- A cover page (large cover photo slot, oversized centered title, muted
-- address/date, whitespace, a small-print company footer, then a rule
-- separating it from the body) followed by five numbered sections, each with
-- a summary line and a 2-photo slot row. Photo numbering is continuous
-- across sections (1-10) rather than restarting per section, matching how
-- multi-section reports are usually referenced ("see photo 7").
--
-- Centering only renders correctly because of the TextAlign extension added
-- alongside this migration (apps/web/src/features/projects/pages/
-- ProjectPageEditorPage.tsx) -- without it Tiptap's default schema has no
-- node/mark for text-align and silently drops the style attribute on parse.
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-002-prebuilt-report-2up',
  NULL,
  NULL,
  '002: Pre-Built Report (2 Photos per Page)',
  jsonb_build_object(
    'style', 'report',
    'description', 'Cover page plus five sections with a 2-photo row each -- a general-purpose site visit or inspection report.',
